use quince_core::types::{Side,Trade};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"fast_alpha",min:0.001,max:1.},IndicatorParameter{name:"slow_alpha",min:0.001,max:1.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_chaikin_oscillator",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{f:f64,s:f64,ef:f64,es:f64}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{if x[0]>=x[1]{return Err(CustomIndicatorError::Construction{indicator:D.name,reason:"fast_alpha must be lower than slow_alpha"})}Ok(Box::new(I{f:x[0],s:x[1],ef:0.,es:0.}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{let flow=if t.side==Side::Buy{t.price*t.qty}else{-t.price*t.qty};self.ef=self.f*flow+(1.-self.f)*self.ef;self.es=self.s*flow+(1.-self.s)*self.es;Some(self.ef-self.es)}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;fn t()->Trade{Trade{price:2.,qty:1.,time:Utc::now(),side:Side::Buy,trade_id:1}}#[test]fn oscillator(){assert!(create(&[0.1,0.5]).unwrap().on_trade(&t()).unwrap()<0.);}#[test]fn invalid(){assert!(create(&[0.5,0.1]).is_err());}}
